def get_bbox_center(comp):
    r_min, r_max = min(p[0] for p in comp), max(p[0] for p in comp)
    c_min, c_max = min(p[1] for p in comp), max(p[1] for p in comp)
    return (r_min + r_max) // 2, (c_min + c_max) // 2

def get_missing(comp):
    r, rr, c, cc = min(p[0] for p in comp), max(p[0] for p in comp), min(p[1] for p in comp), max(p[1] for p in comp)
    all_4 = {(r, c), (r, cc), (rr, c), (rr, cc)}
    return (all_4 - set(comp)).pop()

